const POPULAR = ['getting-started', 'camera', 'physics', 'adding-bodies', 'controls', 'troubleshooting'];

type View =
  | { kind: 'chapter'; chapter: Chapter; missing?: string }
  | { kind: 'glossary'; focus?: string }
  | { kind: 'faq'; focus?: number };

function fill(text: string, vars: Record<string, string | number>): string {
  return text.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m));
}

/** Russian plural form: 1 глава, 2–4 главы, 5+ глав (11–14 always the last form). */
function ruPlural(n: number, one: string, few: string, many: string): string {
  const d = n % 10;
  const h = n % 100;
  if (h >= 11 && h <= 14) return many;
  if (d === 1) return one;
  if (d >= 2 && d <= 4) return few;
  return many;
}

function statsText(lang: Lang): string {
  const c = CHAPTERS.length;
  const g = GLOSSARY.length;
  const f = FAQ.length;
  if (lang === 'ru') {
    return `${c} ${ruPlural(c, 'глава', 'главы', 'глав')} · ${g} ${ruPlural(g, 'термин', 'термина', 'терминов')} · ${f} ${ruPlural(f, 'вопрос', 'вопроса', 'вопросов')}`;
  }
  return `${c} ${c === 1 ? 'chapter' : 'chapters'} · ${g} ${g === 1 ? 'term' : 'terms'} · ${f} ${f === 1 ? 'question' : 'questions'}`;
}

function viewOf(rest: string[]): View {
  const [first, second] = rest;
  if (first === 'glossary') return second ? { kind: 'glossary', focus: second } : { kind: 'glossary' };
  if (first === 'faq') {
    const n = second !== undefined ? Number(second) : NaN;
    return Number.isInteger(n) && n >= 0 && n < FAQ.length ? { kind: 'faq', focus: n } : { kind: 'faq' };
  }
  const fallback = chapterById(DEFAULT_CHAPTER) ?? CHAPTERS[0]!;
  if (!first) return { kind: 'chapter', chapter: fallback };
  const ch = chapterById(first);
  return ch ? { kind: 'chapter', chapter: ch } : { kind: 'chapter', chapter: fallback, missing: first };
}

function hitPath(hit: HandbookHit): string {
  if (hit.type === 'glossary') return '/handbook/glossary/' + encodeURIComponent(hit.id);
  if (hit.type === 'faq') return '/handbook/faq/' + hit.id.replace(/^faq:/, '');
  return '/handbook/' + encodeURIComponent(hit.id);
}

function partOf(id: string) {
  return HANDBOOK_PARTS.find((p) => p.chapters.includes(id));
}

/** Highlights the query words in a text (case-insensitive, е/ё folded). */
function Highlight({ text, query }: { text: string; query: string }) {
  const words = query
    .toLowerCase()
    .split(/\s+/)
    .filter((w) => w.length > 1)
    .map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/[её]/g, '[её]'));
  if (!words.length) return <>{text}</>;
  const re = new RegExp('(' + words.join('|') + ')', 'gi');
  const parts = text.split(re);
  return (
    <>
      {parts.map((p, i) => (i % 2 === 1 ? <mark key={i} className="hb-mark">{p}</mark> : <Fragment key={i}>{p}</Fragment>))}
    </>
  );
}

/** Arrow-key navigation between the links of a list (Up/Down, Home/End). */
function arrowNav(e: KeyboardEvent<HTMLElement>) {
  if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key)) return;
  const items = Array.from(e.currentTarget.querySelectorAll<HTMLElement>('[data-hb-nav]'));
  if (!items.length) return;
  const i = items.indexOf(document.activeElement as HTMLElement);
  let j = i;
  if (e.key === 'ArrowDown') j = i < 0 ? 0 : Math.min(items.length - 1, i + 1);
  if (e.key === 'ArrowUp') j = i < 0 ? 0 : Math.max(0, i - 1);
  if (e.key === 'Home') j = 0;
  if (e.key === 'End') j = items.length - 1;
  e.preventDefault();
  items[j]?.focus();
}

