/** "Ctrl+Z / Ctrl+Shift+Z (⌘ on macOS)" → key caps, keeping separators and remarks as text. */
function Keys({ combo }: { combo: string }) {
  const m = /^(.*?)(\s*\(.*\))?$/.exec(combo);
  const main = m?.[1] ?? combo;
  const remark = m?.[2] ?? '';
  return (
    <span className="hb-keys">
      {main.split(' / ').map((alt, i) => (
        <Fragment key={i}>
          {i > 0 && <span className="hb-keys__or">/</span>}
          {alt.split('+').map((k, j) => (
            <Fragment key={j}>
              {j > 0 && <span className="hb-keys__plus">+</span>}
              <kbd className="hb-kbd">{k.trim()}</kbd>
            </Fragment>
          ))}
        </Fragment>
      ))}
      {remark && <span className="hb-keys__remark">{remark.trim()}</span>}
    </span>
  );
}

function Callout({ kind, text, lang }: { kind: 'note' | 'tip' | 'warning'; text: LocalizedText; lang: Lang }) {
  const icon = kind === 'warning' ? 'warning' : kind === 'tip' ? 'sparkle' : 'info';
  return (
    <aside className={'hb-callout hb-callout--' + kind} aria-label={U[kind][lang]}>
      <span className="hb-callout__icon" aria-hidden="true">
        <Icon name={icon} size={18} />
      </span>
      <div>
        <div className="hb-callout__title">{U[kind][lang]}</div>
        <p>{text[lang]}</p>
      </div>
    </aside>
  );
}

function BlockView({ block, lang, headingId }: { block: Block; lang: Lang; headingId?: string }): ReactNode {
  switch (block.kind) {
    case 'p':
      return <p className="hb-p">{block.text[lang]}</p>;
    case 'h':
      return (
        <h3 className="hb-h3" id={headingId} tabIndex={-1}>
          {block.text[lang]}
        </h3>
      );
    case 'steps':
      return (
        <div className="hb-steps">
          {block.title && <div className="hb-steps__title">{block.title[lang]}</div>}
          <ol className="hb-steps__list">
            {block.items.map((it, i) => (
              <li key={i}>
                <span className="hb-steps__n" aria-hidden="true">{i + 1}</span>
                <span>{it[lang]}</span>
              </li>
            ))}
          </ol>
        </div>
      );
    case 'list':
      return (
        <ul className="hb-list">
          {block.items.map((it, i) => (
            <li key={i}>{it[lang]}</li>
          ))}
        </ul>
      );
    case 'table':
      return (
        <figure className="hb-figure">
          {block.caption && <figcaption className="hb-table-caption">{block.caption[lang]}</figcaption>}
          <div className="hb-table-wrap" tabIndex={0} role="region" aria-label={block.caption ? block.caption[lang] : block.head.map((h) => h[lang]).join(', ')}>
            <table className="hb-table">
              <thead>
                <tr>
                  {block.head.map((h, i) => (
                    <th key={i} scope="col">{h[lang]}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {block.rows.map((row, r) => (
                  <tr key={r}>
                    {row.map((cell, c) =>
                      c === 0 ? (
                        <th key={c} scope="row">{cell[lang]}</th>
                      ) : (
                        <td key={c}>{cell[lang]}</td>
                      ),
                    )}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </figure>
      );
    case 'note':
    case 'tip':
    case 'warning':
      return <Callout kind={block.kind} text={block.text} lang={lang} />;
    case 'feature':
      return <FeatureBadge featureKey={block.feature} lang={lang} />;
    case 'formula':
      return (
        <figure className="hb-formula">
          <div className="hb-formula__label">{U.formula[lang]}</div>
          <code className="hb-formula__expr">{block.formula}</code>
          <figcaption className="hb-formula__text">{block.text[lang]}</figcaption>
        </figure>
      );
    case 'example':
      return (
        <section className="hb-example" aria-label={block.title[lang]}>
          <div className="hb-example__eyebrow">{U.tryIt[lang]}</div>
          <h4 className="hb-example__title">{block.title[lang]}</h4>
          <ol className="hb-example__steps">
            {block.steps.map((s, i) => (
              <li key={i}>{s[lang]}</li>
            ))}
          </ol>
          <div className="hb-example__expect">
            <div className="hb-example__expect-label">{U.expect[lang]}</div>
            <p>{block.expect[lang]}</p>
          </div>
        </section>
      );
    case 'link': {
      const target = chapterById(block.chapter);
      return (
        <a className="hb-crosslink" href={'#/handbook/' + encodeURIComponent(block.chapter)}>
          <span className="hb-crosslink__text">
            <span className="hb-crosslink__label">{block.text[lang]}</span>
            {target && <span className="hb-crosslink__chapter">{target.title[lang]}</span>}
          </span>
          <span className="hb-crosslink__arrow" aria-hidden="true">→</span>
        </a>
      );
    }
    case 'controls':
      return <ControlsTable lang={lang} />;
  }
}

