function ChapterView({ view, lang }: { view: Extract<View, { kind: 'chapter' }>; lang: Lang }) {
  const ch = view.chapter;
  const index = CHAPTERS.indexOf(ch);
  const prev = index > 0 ? CHAPTERS[index - 1] : undefined;
  const next = index < CHAPTERS.length - 1 ? CHAPTERS[index + 1] : undefined;
  const part = partOf(ch.id);
  const minutes = useMemo(() => Math.max(1, Math.round(chapterText(ch, lang).split(/\s+/).length / 200)), [ch, lang]);
  const headings = ch.blocks
    .map((b, i) => ({ b, i }))
    .filter((x): x is { b: Extract<Block, { kind: 'h' }>; i: number } => x.b.kind === 'h');
  const hid = (i: number) => 'hb-' + ch.id + '-h' + i;

  return (
    <article className="hb-article" aria-labelledby="hb-chapter-title">
      {view.missing && (
        <div className="hb-callout hb-callout--warning hb-missing" role="alert">
          <span className="hb-callout__icon" aria-hidden="true">
            <Icon name="warning" size={18} />
          </span>
          <div>
            <div className="hb-callout__title">{U.notFoundTitle[lang]}</div>
            <p>{fill(U.notFoundText[lang], { id: view.missing })}</p>
          </div>
        </div>
      )}
      <header className="hb-article__header">
        <div className="hb-article__eyebrow">
          {part && <span>{part.title[lang]}</span>}
          <span aria-hidden="true">·</span>
          <span>{fill(U.chapterOf[lang], { n: index + 1, total: CHAPTERS.length })}</span>
          <span aria-hidden="true">·</span>
          <span>{fill(U.minutes[lang], { n: minutes })}</span>
        </div>
        <h2 className="hb-article__title" id="hb-chapter-title" tabIndex={-1}>
          {ch.title[lang]}
        </h2>
        <p className="hb-article__summary">{ch.summary[lang]}</p>
      </header>

      {headings.length >= 2 && (
        <nav className="hb-onpage" aria-label={U.onThisPage[lang]}>
          <div className="hb-onpage__title">{U.onThisPage[lang]}</div>
          <ul>
            {headings.map(({ b, i }) => (
              <li key={i}>
                <button
                  type="button"
                  className="hb-onpage__link"
                  onClick={() => {
                    const el = document.getElementById(hid(i));
                    el?.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    el?.focus({ preventScroll: true });
                  }}
                >
                  {b.text[lang]}
                </button>
              </li>
            ))}
          </ul>
        </nav>
      )}

      <div className="hb-prose">
        {ch.blocks.map((b, i) => (
          <BlockView key={ch.id + ':' + i} block={b} lang={lang} headingId={b.kind === 'h' ? hid(i) : undefined} />
        ))}
      </div>

      <nav className="hb-pager" aria-label={U.previous[lang] + ' / ' + U.next[lang]}>
        {prev ? (
          <a className="hb-pager__link hb-pager__link--prev" href={'#/handbook/' + prev.id}>
            <span className="hb-pager__dir">← {U.previous[lang]}</span>
            <span className="hb-pager__title">{prev.title[lang]}</span>
          </a>
        ) : (
          <span />
        )}
        {next ? (
          <a className="hb-pager__link hb-pager__link--next" href={'#/handbook/' + next.id}>
            <span className="hb-pager__dir">{U.next[lang]} →</span>
            <span className="hb-pager__title">{next.title[lang]}</span>
          </a>
        ) : (
          <span />
        )}
      </nav>
    </article>
  );
}

function GlossaryView({ lang, focus }: { lang: Lang; focus?: string }) {
  const [filter, setFilter] = useState('');
  const entries = useMemo(() => {
    const f = filter.trim().toLowerCase().replace(/ё/g, 'е');
    const sorted = [...GLOSSARY].sort((a, b) => a.term[lang].localeCompare(b.term[lang], lang));
    if (!f) return sorted;
    return sorted.filter((g) => (g.term[lang] + ' ' + g.definition[lang]).toLowerCase().replace(/ё/g, 'е').includes(f));
  }, [filter, lang]);
  const groups = useMemo(() => {
    const out: { letter: string; items: typeof GLOSSARY }[] = [];
    for (const g of entries) {
      const letter = g.term[lang].charAt(0).toUpperCase();
      const last = out[out.length - 1];
      if (last && last.letter === letter) last.items.push(g);
      else out.push({ letter, items: [g] });
    }
    return out;
  }, [entries, lang]);

  useEffect(() => {
    if (!focus) return;
    const el = document.getElementById('hb-term-' + focus);
    if (el) {
      el.scrollIntoView({ block: 'center' });
      el.focus({ preventScroll: true });
    }
  }, [focus]);

  return (
    <article className="hb-article" aria-labelledby="hb-chapter-title">
      <header className="hb-article__header">
        <div className="hb-article__eyebrow">
          <span>{statsText(lang)}</span>
        </div>
        <h2 className="hb-article__title" id="hb-chapter-title" tabIndex={-1}>
          {U.glossaryTitle[lang]}
        </h2>
        <p className="hb-article__summary">{U.glossaryLead[lang]}</p>
      </header>
      <label className="hb-filter">
        <span className="hb-visually-hidden">{U.filterTerms[lang]}</span>
        <Icon name="search" size={16} />
        <input type="search" value={filter} onChange={(e) => setFilter(e.target.value)} placeholder={U.filterTerms[lang]} />
      </label>
      {groups.length === 0 && <p className="hb-empty">{fill(U.noTerms[lang], { q: filter })}</p>}
      {groups.map((grp) => (
        <section key={grp.letter} className="hb-gloss-group" aria-label={grp.letter}>
          <div className="hb-gloss-letter" aria-hidden="true">{grp.letter}</div>
          <dl className="hb-gloss">
            {grp.items.map((g) => {
              const ch = g.chapter ? chapterById(g.chapter) : undefined;
              return (
                <div key={g.id} id={'hb-term-' + g.id} tabIndex={-1} className={'hb-gloss__item' + (focus === g.id ? ' is-focused' : '')}>
                  <dt>{g.term[lang]}</dt>
                  <dd>
                    {g.definition[lang]}
                    {ch && (
                      <a className="hb-gloss__more" href={'#/handbook/' + ch.id}>
                        {fill(U.readChapter[lang], { title: ch.title[lang] })} →
                      </a>
                    )}
                  </dd>
                </div>
              );
            })}
          </dl>
        </section>
      ))}
    </article>
  );
}

function FaqView({ lang, focus }: { lang: Lang; focus?: number }) {
  useEffect(() => {
    if (focus === undefined) return;
    const el = document.getElementById('hb-faq-' + focus);
    if (el) {
      el.scrollIntoView({ block: 'center' });
      el.querySelector('summary')?.focus({ preventScroll: true });
    }
  }, [focus]);
  return (
    <article className="hb-article" aria-labelledby="hb-chapter-title">
      <header className="hb-article__header">
        <h2 className="hb-article__title" id="hb-chapter-title" tabIndex={-1}>
          {U.faqTitle[lang]}
        </h2>
        <p className="hb-article__summary">{U.faqLead[lang]}</p>
      </header>
      <div className="hb-faq">
        {FAQ.map((f, i) => {
          const ch = f.chapter ? chapterById(f.chapter) : undefined;
          return (
            <details key={i} id={'hb-faq-' + i} className="hb-faq__item" open={focus === i ? true : undefined}>
              <summary className="hb-faq__q">
                <span>{f.q[lang]}</span>
                <span className="hb-faq__chev" aria-hidden="true" />
              </summary>
              <div className="hb-faq__a">
                <p>{f.a[lang]}</p>
                {ch && (
                  <a className="hb-gloss__more" href={'#/handbook/' + ch.id}>
                    {fill(U.readChapter[lang], { title: ch.title[lang] })} →
                  </a>
                )}
              </div>
            </details>
          );
        })}
      </div>
    </article>
  );
}

function SearchResults({ query, hits, lang, onPick }: { query: string; hits: HandbookHit[]; lang: Lang; onPick: (h: HandbookHit) => void }) {
  const q = query.trim();
  const short = q.split(/\s+/).every((w) => w.length < 2);
  const typeLabel = (t: HandbookHit['type']) => (t === 'chapter' ? U.typeChapter : t === 'glossary' ? U.typeGlossary : U.typeFaq)[lang];
  return (
    <section className="hb-article hb-results" aria-labelledby="hb-results-title" aria-live="polite">
      <header className="hb-article__header">
        <h2 className="hb-article__title hb-results__title" id="hb-results-title">
          {fill(U.results[lang], { q })}
        </h2>
        {!short && <div className="hb-article__eyebrow">{fill(U.resultCount[lang], { n: hits.length })}</div>}
      </header>
      {short ? (
        <p className="hb-empty">{U.tooShort[lang]}</p>
      ) : hits.length === 0 ? (
        <div className="hb-empty">
          <p>{fill(U.noResults[lang], { q })}</p>
          <div className="hb-empty__title">{U.tryThese[lang]}</div>
          <div className="hb-chips">
            {POPULAR.map((id) => {
              const ch = chapterById(id);
              return ch ? (
                <a key={id} className="hb-chip" href={'#/handbook/' + id} onClick={() => onPick({ type: 'chapter', id, chapter: id, title: '', snippet: '', score: 0 })}>
                  {ch.title[lang]}
                </a>
              ) : null;
            })}
          </div>
        </div>
      ) : (
        <ul className="hb-results__list" onKeyDown={arrowNav}>
          {hits.map((h) => {
            const parent = h.type !== 'chapter' && h.chapter ? chapterById(h.chapter) : undefined;
            return (
              <li key={h.type + ':' + h.id}>
                <a
                  className="hb-result"
                  data-hb-nav=""
                  href={'#' + hitPath(h)}
                  onClick={(e) => {
                    e.preventDefault();
                    onPick(h);
                  }}
                >
                  <span className={'hb-result__type hb-result__type--' + h.type}>{typeLabel(h.type)}</span>
                  <span className="hb-result__title">
                    <Highlight text={h.title} query={q} />
                  </span>
                  <span className="hb-result__snippet">
                    <Highlight text={h.snippet} query={q} />
                  </span>
                  {parent && <span className="hb-result__where">{parent.title[lang]}</span>}
                </a>
              </li>
            );
          })}
        </ul>
      )}
    </section>
  );
}

// ---- Page ----------------------------------------------------------------------------------------------------------

export function HandbookPage() {
  const lang = useLang();
  const route = useRoute();
  const view = useMemo(() => viewOf(route.rest), [route.rest]);
  const [query, setQuery] = useState(() => route.params.get('q') ?? '');
  const searchRef = useRef<HTMLInputElement>(null);
  const mainRef = useRef<HTMLDivElement>(null);
  const hits = useMemo(() => searchHandbook(query, lang, 30), [query, lang]);
  const searching = query.trim().length > 0;
  const viewKey = view.kind === 'chapter' ? 'chapter:' + view.chapter.id : view.kind;
  const firstRender = useRef(true);

  // A ?q= in a new route opens with that search.
  useEffect(() => {
    const q = route.params.get('q');
    if (q !== null) setQuery(q);
  }, [route.serial, route.params]);

  // New chapter: back to the top of the article and focus its title (not on first load, to keep the page scroll natural).
  useEffect(() => {
    if (firstRender.current) {
      firstRender.current = false;
      return;
    }
    if (view.kind === 'glossary' && view.focus) return;
    if (view.kind === 'faq' && view.focus !== undefined) return;
    const top = mainRef.current?.getBoundingClientRect().top ?? 0;
    if (top < 0 || top > window.innerHeight) window.scrollTo({ top: window.scrollY + top - 80, behavior: 'auto' });
    document.getElementById('hb-chapter-title')?.focus({ preventScroll: true });
  }, [viewKey, view]);

  // "/" focuses the search unless the user is typing somewhere.
  useEffect(() => {
    const onKey = (e: globalThis.KeyboardEvent) => {
      if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey) return;
      const t = e.target as HTMLElement | null;
      if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
      e.preventDefault();
      searchRef.current?.focus();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const pick = (h: HandbookHit) => {
    setQuery('');
    navigate(hitPath(h));
  };

  const currentChapterId = view.kind === 'chapter' ? view.chapter.id : '';
  const selectValue = view.kind === 'chapter' ? view.chapter.id : view.kind;

  return (
    <div className="hb-page">
      <header className="hb-hero">
        <div className="hb-hero__glow" aria-hidden="true" />
        <div className="hb-hero__inner">
          <div className="hb-eyebrow">
            <Icon name="book" size={16} />
            <span>{U.eyebrow[lang]}</span>
          </div>
          <h1 className="hb-hero__title">{U.title[lang]}</h1>
          <p className="hb-hero__lead">{U.lead[lang]}</p>
          <form
            className="hb-search"
            role="search"
            onSubmit={(e) => {
              e.preventDefault();
              if (hits[0]) pick(hits[0]);
            }}
          >
            <label className="hb-visually-hidden" htmlFor="hb-search-input">
              {U.searchLabel[lang]}
            </label>
            <span className="hb-search__icon" aria-hidden="true">
              <Icon name="search" size={20} />
            </span>
            <input
              id="hb-search-input"
              ref={searchRef}
              className="hb-search__input"
              type="search"
              autoComplete="off"
              spellCheck={false}
              value={query}
              placeholder={U.searchPlaceholder[lang]}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Escape' && query) {
                  e.preventDefault();
                  setQuery('');
                }
                if (e.key === 'ArrowDown' && searching) {
                  const first = document.querySelector<HTMLElement>('.hb-results [data-hb-nav]');
                  if (first) {
                    e.preventDefault();
                    first.focus();
                  }
                }
              }}
            />
            {query ? (
              <button type="button" className="hb-search__clear" onClick={() => { setQuery(''); searchRef.current?.focus(); }} aria-label={U.clear[lang]}>
                <Icon name="close" size={16} />
              </button>
            ) : (
              <kbd className="hb-kbd hb-search__hint" title={U.searchHint[lang]}>/</kbd>
            )}
          </form>
          <div className="hb-hero__meta">
            <span>{statsText(lang)}</span>
            <span aria-hidden="true">·</span>
            <span>{U.bilingual[lang]}</span>
          </div>
          <nav className="hb-tabs" aria-label={U.sections[lang]}>
            <a className="hb-tab" href={'#/handbook/' + (currentChapterId || DEFAULT_CHAPTER)} aria-current={view.kind === 'chapter' && !searching ? 'page' : undefined} onClick={() => setQuery('')}>
              <Icon name="book" size={16} />
              {U.chapters[lang]}
            </a>
            <a className="hb-tab" href="#/handbook/glossary" aria-current={view.kind === 'glossary' && !searching ? 'page' : undefined} onClick={() => setQuery('')}>
              <Icon name="library" size={16} />
              {U.glossary[lang]}
            </a>
            <a className="hb-tab" href="#/handbook/faq" aria-current={view.kind === 'faq' && !searching ? 'page' : undefined} onClick={() => setQuery('')}>
              <Icon name="help" size={16} />
              {U.faq[lang]}
            </a>
          </nav>
        </div>
      </header>

      <div className="hb-layout">
        <aside className="hb-sidebar">
          <label className="hb-mobile-select">
            <span className="hb-mobile-select__label">{U.chooseChapter[lang]}</span>
            <select
              value={selectValue}
              onChange={(e) => {
                setQuery('');
                navigate('/handbook/' + e.target.value);
              }}
            >
              {HANDBOOK_PARTS.map((p) => (
                <optgroup key={p.id} label={p.title[lang]}>
                  {p.chapters.map((id) => {
                    const ch = chapterById(id);
                    return ch ? (
                      <option key={id} value={id}>
                        {CHAPTERS.indexOf(ch) + 1}. {ch.title[lang]}
                      </option>
                    ) : null;
                  })}
                </optgroup>
              ))}
              <optgroup label={U.glossary[lang] + ' · ' + U.faq[lang]}>
                <option value="glossary">{U.glossaryTitle[lang]}</option>
                <option value="faq">{U.faqTitle[lang]}</option>
              </optgroup>
            </select>
          </label>

          <nav className="hb-toc" aria-label={U.contents[lang]} onKeyDown={arrowNav}>
            <div className="hb-toc__title">{U.contents[lang]}</div>
            {HANDBOOK_PARTS.map((p) => (
              <div key={p.id} className="hb-toc__part">
                <div className="hb-toc__part-title" id={'hb-part-' + p.id}>
                  {p.title[lang]}
                </div>
                <ul aria-labelledby={'hb-part-' + p.id}>
                  {p.chapters.map((id) => {
                    const ch = chapterById(id);
                    if (!ch) return null;
                    const active = !searching && id === currentChapterId;
                    return (
                      <li key={id}>
                        <a
                          className={'hb-toc__link' + (active ? ' is-active' : '')}
                          href={'#/handbook/' + id}
                          data-hb-nav=""
                          aria-current={active ? 'page' : undefined}
                          onClick={() => setQuery('')}
                        >
                          <span className="hb-toc__num">{String(CHAPTERS.indexOf(ch) + 1).padStart(2, '0')}</span>
                          <span>{ch.title[lang]}</span>
                        </a>
                      </li>
                    );
                  })}
                </ul>
              </div>
            ))}
            <div className="hb-toc__part">
              <ul>
                <li>
                  <a className={'hb-toc__link' + (!searching && view.kind === 'glossary' ? ' is-active' : '')} href="#/handbook/glossary" data-hb-nav="" aria-current={!searching && view.kind === 'glossary' ? 'page' : undefined} onClick={() => setQuery('')}>
                    <span className="hb-toc__num">Aa</span>
                    <span>{U.glossaryTitle[lang]}</span>
                  </a>
                </li>
                <li>
                  <a className={'hb-toc__link' + (!searching && view.kind === 'faq' ? ' is-active' : '')} href="#/handbook/faq" data-hb-nav="" aria-current={!searching && view.kind === 'faq' ? 'page' : undefined} onClick={() => setQuery('')}>
                    <span className="hb-toc__num">?</span>
                    <span>{U.faqTitle[lang]}</span>
                  </a>
                </li>
              </ul>
            </div>
          </nav>
        </aside>

        <main className="hb-main" ref={mainRef} id="hb-main">
          {searching ? (
            <SearchResults query={query} hits={hits} lang={lang} onPick={pick} />
          ) : view.kind === 'chapter' ? (
            <ChapterView key={view.chapter.id} view={view} lang={lang} />
          ) : view.kind === 'glossary' ? (
            <GlossaryView lang={lang} focus={view.focus} />
          ) : (
            <FaqView lang={lang} focus={view.focus} />
          )}
        </main>
      </div>
    </div>
  );
}

export default HandbookPage;
